  (418, 1, '<bike-registration-20260505@security.example.edu.cn>', 'Bicycle registration approved', 'campus-security@example.edu.cn', '["lin.che@example.com"]', '[]', '[]', '2026-05-05T06:18:00Z', 'The blue commuter shuttle has been registered in the East Gate parking area, valid until June 30, electronic tag number B7-194.', '', 1, 0, 0, NULL, NULL, '{"X-Bike-Tag": "B7-194"}', 418, 121, '2026-05-05T06:19:10Z'),
  (441, 1, '<travel-reimbursement-20260508@finance.example.edu.cn>', 'Academic conference travel reimbursement received', 'finance@cs.example.edu.cn', '["lin.che@example.com"]', '[]', '[]', '2026-05-08T03:44:00Z', 'The 1,268 yuan reimbursement for Nanjing conference travel has been transferred to the campus bank card, voucher number F2026050817.', '', 0, 0, 0, NULL, NULL, '{"X-Voucher": "F2026050817"}', 441, 123, '2026-05-08T03:45:33Z'),
